export type ThemeColors = typeof palette.light;
export type ColorScheme = "light" | "dark";

export const radius = { xs: 6, sm: 8, md: 12, lg: 16, xl: 20, "2xl": 24, "3xl": 32, full: 9999 };

/** 4pt spacing scale: space(4) === 16. */
export const space = (n: number) => n * 4;

export const fontSize = {
  xs: 12,
  sm: 14,
  base: 16,
  lg: 18,
  xl: 20,
  "2xl": 24,
  "3xl": 30,
  "4xl": 36,
};

export const fontWeight = {
  regular: "400",
  medium: "500",
  semibold: "600",
  bold: "700",
} as const;

export const fontFamily = {
  mono: Platform.select({
    ios: "Menlo",
    android: "monospace",
    default: "ui-monospace, Menlo, monospace",
  }),
};

/** Animated: use the native driver everywhere except react-native-web. */
export const nativeDriver = Platform.OS !== "web";

/** Cross-platform elevation. Level 0–4. */
export function shadow(level: 0 | 1 | 2 | 3 | 4, scheme: ColorScheme = "light"): ViewStyle {
  if (level === 0) return {};
  const dark = scheme === "dark";
  const y = [0, 1, 4, 10, 18][level];
  const blur = [0, 3, 12, 28, 44][level];
  const alpha = (dark ? [0, 0.4, 0.5, 0.55, 0.6] : [0, 0.06, 0.08, 0.12, 0.16])[level];
  if (Platform.OS === "web") {
    return { boxShadow: `0px ${y}px ${blur}px rgba(0,0,0,${alpha})` } as ViewStyle;
  }
  return {
    shadowColor: "#000",
    shadowOffset: { width: 0, height: y },
    shadowOpacity: alpha,
    shadowRadius: blur / 2,
    elevation: level * 3,
  };
}

/** Hex color to rgba(). */
export function alpha(hex: string, a: number) {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.replace(/./g, (c) => c + c) : h, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

type ThemeValue = {
  scheme: ColorScheme;
  colors: ThemeColors;
  radius: typeof radius;
  space: typeof space;
  fontSize: typeof fontSize;
  fontWeight: typeof fontWeight;
  shadow: (level: 0 | 1 | 2 | 3 | 4) => ViewStyle;
};

const ThemeContext = React.createContext<{
  scheme?: ColorScheme;
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
} | null>(null);

export function ThemeProvider({
  scheme,
  colors,
  children,
}: {
  /** Force a scheme. Defaults to the device setting. */
  scheme?: ColorScheme;
  /** Override tokens per scheme, e.g. `{ light: { brand: "#7c3aed" } }`. */
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => ({ scheme, colors }), [scheme, colors]);
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useTheme(): ThemeValue {
  const ctx = React.useContext(ThemeContext);
  const system = useColorScheme();
  const scheme: ColorScheme = ctx?.scheme ?? (system === "dark" ? "dark" : "light");
  return React.useMemo(
    () => ({
      scheme,
      colors: { ...palette[scheme], ...(ctx?.colors?.[scheme] ?? {}) },
      radius,
      space,
      fontSize,
      fontWeight,
      shadow: (level: 0 | 1 | 2 | 3 | 4) => shadow(level, scheme),
    }),
    [scheme, ctx?.colors],
  );
}

import * as React from "react";
import { Animated, Pressable, StyleSheet, Text, View } from "react-native";
import { Icon, type IconName } from "@/components/native/icon";
import { Backdrop, useBackHandler, useOverlayTransition } from "@/components/native/overlay";
import { Portal } from "@/components/native/portal";
import { useTheme } from "@/components/native/theme";

export type ActionSheetOption = {
  label: string;
  icon?: IconName;
  destructive?: boolean;
  disabled?: boolean;
  onPress: () => void;
};

export type ActionSheetProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: string;
  message?: string;
  options: ActionSheetOption[];
  cancelLabel?: string;
  bottomInset?: number;
};

export function ActionSheet({
  open,
  onOpenChange,
  title,
  message,
  options,
  cancelLabel = "Cancel",
  bottomInset = 24,
}: ActionSheetProps) {
  const { colors } = useTheme();
  const { mounted, progress } = useOverlayTransition(open);
  const close = React.useCallback(() => onOpenChange(false), [onOpenChange]);
  useBackHandler(open, close);

  if (!mounted) return null;

  const row = (o: ActionSheetOption, i: number) => (
    <React.Fragment key={o.label}>
      {(i > 0 || title || message) && (
        <View style={[styles.sep, { backgroundColor: colors.border }]} />
      )}
      <Pressable
        accessibilityRole="button"
        disabled={o.disabled}
        onPress={() => {
          close();
          o.onPress();
        }}
        style={({ pressed }) => [
          styles.option,
          pressed && { backgroundColor: colors.accent },
          o.disabled && { opacity: 0.4 },
        ]}
      >
        {o.icon && (
          <Icon
            name={o.icon}
            size={20}
            color={o.destructive ? colors.destructive : colors.foreground}
          />
        )}
        <Text
          style={[
            styles.optionText,
            { color: o.destructive ? colors.destructive : colors.foreground },
          ]}
        >
          {o.label}
        </Text>
      </Pressable>
    </React.Fragment>
  );

  return (
    <Portal>
      <View style={[StyleSheet.absoluteFill, styles.end, { paddingBottom: bottomInset }]}>
        <Backdrop progress={progress} onPress={close} />
        <Animated.View
          accessibilityViewIsModal
          style={{
            gap: 8,
            transform: [
              { translateY: progress.interpolate({ inputRange: [0, 1], outputRange: [400, 0] }) },
            ],
          }}
        >
          <View style={[styles.group, { backgroundColor: colors.card }]}>
            {(title || message) && (
              <View style={styles.head}>
                {title && (
                  <Text style={[styles.title, { color: colors.mutedForeground }]}>{title}</Text>
                )}
                {message && (
                  <Text style={[styles.message, { color: colors.mutedForeground }]}>{message}</Text>
                )}
              </View>
            )}
            {options.map(row)}
          </View>
          <Pressable
            accessibilityRole="button"
            onPress={close}
            style={({ pressed }) => [
              styles.group,
              styles.cancel,
              { backgroundColor: pressed ? colors.accent : colors.card },
            ]}
          >
            <Text style={[styles.cancelText, { color: colors.foreground }]}>{cancelLabel}</Text>
          </Pressable>
        </Animated.View>
      </View>
    </Portal>
  );
}

const styles = StyleSheet.create({
  end: { justifyContent: "flex-end", paddingHorizontal: 10 },
  group: { borderRadius: 22, overflow: "hidden" },
  head: { alignItems: "center", paddingHorizontal: 20, paddingVertical: 14, gap: 3 },
  title: { fontSize: 13, fontWeight: "600" },
  message: { fontSize: 13, textAlign: "center", lineHeight: 18 },
  sep: { height: StyleSheet.hairlineWidth },
  option: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 10,
