export type AlertDialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: string;
  icon?: IconName;
  confirmLabel?: string;
  cancelLabel?: string;
  /** Styles the confirm button and icon in red. */
  destructive?: boolean;
  /** May return a promise; the button shows a spinner until it settles. */
  onConfirm: () => void | Promise<void>;
  onCancel?: () => void;
};

/** Requires an explicit choice: no backdrop dismissal, no close button. */
export function AlertDialog({
  open,
  onOpenChange,
  title,
  description,
  icon,
  confirmLabel = "Continue",
  cancelLabel = "Cancel",
  destructive,
  onConfirm,
  onCancel,
}: AlertDialogProps) {
  const { colors, shadow } = useTheme();
  const { mounted, progress } = useOverlayTransition(open);
  const [busy, setBusy] = React.useState(false);

  if (!mounted) return null;

  const confirm = async () => {
    try {
      setBusy(true);
      await onConfirm();
      onOpenChange(false);
    } finally {
      setBusy(false);
    }
  };

  const tone = destructive ? colors.destructive : colors.brand;
  const soft = destructive ? colors.destructiveSoft : colors.brandSoft;

  return (
    <Portal>
      <View style={[StyleSheet.absoluteFill, styles.center]}>
        <Backdrop progress={progress} dismissible={false} />
        <Animated.View
          accessibilityViewIsModal
          accessibilityRole="alert"
          style={[
            styles.panel,
            shadow(4),
            {
              backgroundColor: colors.card,
              borderColor: colors.border,
              opacity: progress,
              transform: [
                { scale: progress.interpolate({ inputRange: [0, 1], outputRange: [1.08, 1] }) },
              ],
            },
          ]}
        >
          <View style={[styles.icon, { backgroundColor: soft }]}>
            <Icon name={icon ?? (destructive ? "trash" : "alert-circle")} size={24} color={tone} />
          </View>
          <Text style={[styles.title, { color: colors.foreground }]}>{title}</Text>
          {description && (
            <Text style={[styles.description, { color: colors.mutedForeground }]}>
              {description}
            </Text>
          )}
          <View style={styles.actions}>
            <Button
              block
              variant={destructive ? "destructive" : "default"}
              loading={busy}
              onPress={confirm}
            >
              {confirmLabel}
            </Button>
            <Button
              block
              variant="ghost"
              disabled={busy}
              onPress={() => {
                onCancel?.();
                onOpenChange(false);
              }}
            >
              {cancelLabel}
            </Button>
          </View>
        </Animated.View>
      </View>
    </Portal>
  );
}

