import * as React from "react";
import { Animated } from "react-native";
import { nativeDriver } from "@/components/native/theme";

/**
 * Springy press feedback. Spread `handlers` on a Pressable and apply `style`
 * to an Animated.View inside (or around) it.
 */
export function usePressScale(to = 0.97) {
  const scale = React.useRef(new Animated.Value(1)).current;

  const animate = React.useCallback(
    (value: number) =>
      Animated.spring(scale, {
        toValue: value,
        useNativeDriver: nativeDriver,
        speed: 40,
        bounciness: value === 1 ? 6 : 0,
      }).start(),
    [scale],
  );

  return {
    style: { transform: [{ scale }] },
    handlers: {
      onPressIn: () => animate(to),
      onPressOut: () => animate(1),
    },
  };
}

import * as React from "react";
import {
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { useTheme } from "@/components/native/theme";

export type CalendarStripProps = {
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (date: Date) => void;
  /** First date in the strip. Defaults to the start of the selected week. */
  start?: Date;
  /** Number of days to show. */
  days?: number;
  /** Dates (YYYY-MM-DD) that get an event dot. */
  marked?: string[];
  locale?: string;
  style?: StyleProp<ViewStyle>;
};

const key = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

const same = (a: Date, b: Date) => key(a) === key(b);

function startOfWeek(d: Date) {
  const s = new Date(d);
  s.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // Monday
  s.setHours(0, 0, 0, 0);
  return s;
}

export function CalendarStrip({
  value,
  defaultValue,
  onValueChange,
  start,
  days = 14,
  marked = [],
  locale = "en-US",
  style,
}: CalendarStripProps) {
  const { colors } = useTheme();
  const [today] = React.useState(() => new Date());
  const [inner, setInner] = React.useState(defaultValue ?? today);
  const selected = value ?? inner;
  const first = start ?? startOfWeek(selected);
  const list = Array.from({ length: days }, (_, i) => {
    const d = new Date(first);
    d.setDate(first.getDate() + i);
    return d;
  });

  return (
    <ScrollView
      horizontal
      showsHorizontalScrollIndicator={false}
      contentContainerStyle={styles.row}
      style={style}
    >
      {list.map((d) => {
        const active = same(d, selected);
        const isToday = same(d, today);
        const dot = marked.includes(key(d));
        return (
          <Pressable
            key={key(d)}
            accessibilityRole="button"
            accessibilityState={{ selected: active }}
            accessibilityLabel={d.toLocaleDateString(locale, {
              weekday: "long",
              month: "long",
              day: "numeric",
            })}
            onPress={() => {
              if (value === undefined) setInner(d);
              onValueChange?.(d);
            }}
            style={({ pressed }) => [
              styles.day,
              {
                backgroundColor: active ? colors.primary : pressed ? colors.accent : colors.card,
                borderColor: active ? colors.primary : colors.border,
              },
            ]}
          >
            <Text
              style={[
                styles.weekday,
                { color: active ? colors.primaryForeground : colors.mutedForeground },
              ]}
            >
              {d.toLocaleDateString(locale, { weekday: "short" }).slice(0, 3)}
            </Text>
            <Text
              style={[
                styles.date,
                { color: active ? colors.primaryForeground : colors.foreground },
              ]}
            >
              {d.getDate()}
            </Text>
            <View
              style={[
                styles.dot,
                {
                  backgroundColor: dot
                    ? active
                      ? colors.primaryForeground
                      : colors.brand
                    : isToday && !active
                      ? colors.borderStrong
                      : "transparent",
                },
              ]}
            />
          </Pressable>
        );
      })}
    </ScrollView>
  );
}

