export function shadow(level: 0 | 1 | 2 | 3 | 4, scheme: ColorScheme = "light"): ViewStyle {
  if (level === 0) return {};
  const dark = scheme === "dark";
  const y = [0, 1, 4, 10, 18][level];
  const blur = [0, 3, 12, 28, 44][level];
  const alpha = (dark ? [0, 0.4, 0.5, 0.55, 0.6] : [0, 0.06, 0.08, 0.12, 0.16])[level];
  if (Platform.OS === "web") {
    return { boxShadow: `0px ${y}px ${blur}px rgba(0,0,0,${alpha})` } as ViewStyle;
  }
  return {
    shadowColor: "#000",
    shadowOffset: { width: 0, height: y },
    shadowOpacity: alpha,
    shadowRadius: blur / 2,
    elevation: level * 3,
  };
}

/** Hex color to rgba(). */
export function alpha(hex: string, a: number) {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.replace(/./g, (c) => c + c) : h, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

type ThemeValue = {
  scheme: ColorScheme;
  colors: ThemeColors;
  radius: typeof radius;
  space: typeof space;
  fontSize: typeof fontSize;
  fontWeight: typeof fontWeight;
  shadow: (level: 0 | 1 | 2 | 3 | 4) => ViewStyle;
};

const ThemeContext = React.createContext<{
  scheme?: ColorScheme;
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
} | null>(null);

export function ThemeProvider({
  scheme,
  colors,
  children,
}: {
  /** Force a scheme. Defaults to the device setting. */
  scheme?: ColorScheme;
  /** Override tokens per scheme, e.g. `{ light: { brand: "#7c3aed" } }`. */
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => ({ scheme, colors }), [scheme, colors]);
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useTheme(): ThemeValue {
  const ctx = React.useContext(ThemeContext);
  const system = useColorScheme();
  const scheme: ColorScheme = ctx?.scheme ?? (system === "dark" ? "dark" : "light");
  return React.useMemo(
    () => ({
      scheme,
      colors: { ...palette[scheme], ...(ctx?.colors?.[scheme] ?? {}) },
      radius,
      space,
      fontSize,
      fontWeight,
      shadow: (level: 0 | 1 | 2 | 3 | 4) => shadow(level, scheme),
    }),
    [scheme, ctx?.colors],
  );
}

import * as React from "react";
import { Animated, StyleSheet, Text, View, type StyleProp, type ViewStyle } from "react-native";
import { Icon } from "@/components/native/icon";
import { nativeDriver, useTheme } from "@/components/native/theme";

export type ChatBubbleProps = {
  children: React.ReactNode;
  /** "me" aligns right with the brand color. */
  from?: "me" | "them";
  time?: string;
  status?: "sending" | "sent" | "read";
  /** Draw the tail. Turn off for grouped messages that follow one another. */
  tail?: boolean;
  /** Animate in when mounted. */
  animate?: boolean;
  style?: StyleProp<ViewStyle>;
};

export function ChatBubble({
  children,
  from = "them",
  time,
  status,
  tail = true,
  animate = true,
  style,
}: ChatBubbleProps) {
  const { colors } = useTheme();
  const me = from === "me";
  const anim = React.useRef(new Animated.Value(animate ? 0 : 1)).current;

  React.useEffect(() => {
    if (!animate) return;
    Animated.spring(anim, {
      toValue: 1,
      useNativeDriver: nativeDriver,
      damping: 16,
      stiffness: 220,
    }).start();
  }, [animate, anim]);

  const bg = me ? colors.brand : colors.muted;
  const fg = me ? colors.brandForeground : colors.foreground;
  const r = 20;

  return (
    <Animated.View
      style={[
        styles.row,
        me ? styles.end : styles.start,
        {
          opacity: anim,
          transform: [
            { translateY: anim.interpolate({ inputRange: [0, 1], outputRange: [10, 0] }) },
            { scale: anim.interpolate({ inputRange: [0, 1], outputRange: [0.94, 1] }) },
          ],
        },
        style,
      ]}
    >
      <View
        style={[
          styles.bubble,
          {
            backgroundColor: bg,
            borderTopLeftRadius: r,
            borderTopRightRadius: r,
            borderBottomLeftRadius: !me && tail ? 6 : r,
            borderBottomRightRadius: me && tail ? 6 : r,
          },
        ]}
      >
        {typeof children === "string" ? (
          <Text style={[styles.text, { color: fg }]}>{children}</Text>
        ) : (
          children
        )}
        {(time || status) && (
          <View style={styles.meta}>
            {time && (
              <Text
                style={[
                  styles.time,
                  { color: me ? "rgba(255,255,255,0.72)" : colors.mutedForeground },
                ]}
              >
                {time}
              </Text>
            )}
            {me && status === "sending" && (
              <Icon name="clock" size={12} color="rgba(255,255,255,0.72)" />
            )}
            {me && status === "sent" && (
              <Icon name="check" size={13} strokeWidth={2.5} color="rgba(255,255,255,0.72)" />
            )}
            {me && status === "read" && (
              <View style={styles.read}>
                <Icon name="check" size={13} strokeWidth={2.5} color="#ffffff" />
                <View style={{ marginLeft: -8 }}>
                  <Icon name="check" size={13} strokeWidth={2.5} color="#ffffff" />
                </View>
              </View>
            )}
          </View>
        )}
      </View>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: "row", marginVertical: 2 },
  start: { justifyContent: "flex-start", paddingRight: 56 },
  end: { justifyContent: "flex-end", paddingLeft: 56 },
  bubble: { paddingHorizontal: 14, paddingTop: 9, paddingBottom: 8, maxWidth: "100%" },
  text: { fontSize: 16, lineHeight: 22 },
  meta: { flexDirection: "row", alignItems: "center", alignSelf: "flex-end", gap: 4, marginTop: 2 },
  time: { fontSize: 11, fontVariant: ["tabular-nums"] },
  read: { flexDirection: "row" },
});

