export type DialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: string;
  description?: string;
  children?: React.ReactNode;
  /** Buttons row at the bottom. */
  footer?: React.ReactNode;
  /** Close on backdrop press and back button. */
  dismissible?: boolean;
  showClose?: boolean;
  style?: StyleProp<ViewStyle>;
};

export function Dialog({
  open,
  onOpenChange,
  title,
  description,
  children,
  footer,
  dismissible = true,
  showClose = true,
  style,
}: DialogProps) {
  const { colors, shadow } = useTheme();
  const { mounted, progress } = useOverlayTransition(open);
  const close = React.useCallback(() => onOpenChange(false), [onOpenChange]);
  useBackHandler(open && dismissible, close);

  if (!mounted) return null;

  return (
    <Portal>
      <View style={[StyleSheet.absoluteFill, styles.center]}>
        <Backdrop progress={progress} onPress={close} dismissible={dismissible} />
        <Animated.View
          accessibilityViewIsModal
          accessibilityRole="alert"
          style={[
            styles.panel,
            shadow(4),
            {
              backgroundColor: colors.card,
              borderColor: colors.border,
              opacity: progress,
              transform: [
                { scale: progress.interpolate({ inputRange: [0, 1], outputRange: [0.92, 1] }) },
                { translateY: progress.interpolate({ inputRange: [0, 1], outputRange: [16, 0] }) },
              ],
            },
            style,
          ]}
        >
          {showClose && dismissible && (
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Close"
              hitSlop={10}
              onPress={close}
              style={[styles.close, { backgroundColor: colors.muted }]}
            >
              <Icon name="x" size={15} strokeWidth={2.5} color={colors.mutedForeground} />
            </Pressable>
          )}
          {(title || description) && (
            <View style={styles.header}>
              {title && <Text style={[styles.title, { color: colors.foreground }]}>{title}</Text>}
              {description && (
                <Text style={[styles.description, { color: colors.mutedForeground }]}>
                  {description}
                </Text>
              )}
            </View>
          )}
          {children}
          {footer && <View style={styles.footer}>{footer}</View>}
        </Animated.View>
      </View>
    </Portal>
  );
}

