/**
 * Portal + PortalHost.
 *
 * Overlays (Dialog, Sheet, Select, Toast…) render into the nearest <PortalHost>
 * so they sit above your navigation. Put one at the root of your app:
 *
 *   <PortalHost>
 *     <Stack />
 *   </PortalHost>
 *
 * Without a host, overlays fall back to a transparent React Native <Modal>.
 */
import * as React from "react";
import { Modal, StyleSheet, View } from "react-native";

type Store = {
  set: (key: string, node: React.ReactNode) => void;
  remove: (key: string) => void;
};

const PortalContext = React.createContext<Store | null>(null);

export function PortalHost({ children }: { children?: React.ReactNode }) {
  const [nodes, setNodes] = React.useState<[string, React.ReactNode][]>([]);

  const store = React.useMemo<Store>(
    () => ({
      set: (key, node) =>
        setNodes((prev) => {
          const i = prev.findIndex(([k]) => k === key);
          if (i === -1) return [...prev, [key, node]];
          const next = prev.slice();
          next[i] = [key, node];
          return next;
        }),
      remove: (key) => setNodes((prev) => prev.filter(([k]) => k !== key)),
    }),
    [],
  );

  return (
    <PortalContext.Provider value={store}>
      <View style={styles.root}>
        {children}
        <View pointerEvents="box-none" style={StyleSheet.absoluteFill}>
          {nodes.map(([key, node]) => (
            <React.Fragment key={key}>{node}</React.Fragment>
          ))}
        </View>
      </View>
    </PortalContext.Provider>
  );
}

export function Portal({ children }: { children: React.ReactNode }) {
  const store = React.useContext(PortalContext);
  const key = React.useId();

  React.useLayoutEffect(() => {
    store?.set(key, children);
  }, [store, key, children]);

  React.useLayoutEffect(() => {
    return () => store?.remove(key);
  }, [store, key]);

  if (store) return null;
  return (
    <Modal transparent visible animationType="none" statusBarTranslucent>
      {children}
    </Modal>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
});

import * as React from "react";
import {
  Animated,
  Easing,
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import Svg, { Circle, Defs, LinearGradient, Stop } from "react-native-svg";
import { useTheme } from "@/components/native/theme";

export type ProgressRingProps = {
  /** 0–100 */
  value: number;
  size?: number;
  strokeWidth?: number;
  /** Two colors draw a gradient arc. */
  colors?: [string, string];
  /** Center content. Defaults to the percentage. */
  children?: React.ReactNode;
  label?: string;
  style?: StyleProp<ViewStyle>;
};

let gid = 0;

export function ProgressRing({
  value,
  size = 120,
  strokeWidth = 10,
  colors: gradient,
  children,
  label,
  style,
}: ProgressRingProps) {
  const { colors } = useTheme();
  const anim = React.useRef(new Animated.Value(0)).current;
  const [shown, setShown] = React.useState(0);
  const id = React.useRef(`ring-${++gid}`).current;

  React.useEffect(() => {
    // SVG props are animated through a listener so it works on every platform.
    const sub = anim.addListener(({ value: v }) => setShown(v));
    Animated.timing(anim, {
      toValue: Math.min(Math.max(value, 0), 100),
      duration: 900,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: false,
    }).start();
    return () => anim.removeListener(sub);
  }, [value, anim]);

  const r = (size - strokeWidth) / 2;
  const c = 2 * Math.PI * r;
  const [from, to] = gradient ?? [colors.brand, colors.brand];

  return (
    <View
      accessibilityRole="progressbar"
      accessibilityValue={{ min: 0, max: 100, now: Math.round(value) }}
      style={[{ width: size, height: size }, style]}
    >
      <View style={{ transform: [{ rotate: "-90deg" }] }}>
        <Svg width={size} height={size}>
          <Defs>
            <LinearGradient id={id} x1="0" y1="0" x2="1" y2="1">
              <Stop offset="0" stopColor={from} />
              <Stop offset="1" stopColor={to} />
            </LinearGradient>
          </Defs>
          <Circle
            cx={size / 2}
            cy={size / 2}
            r={r}
            stroke={colors.muted}
            strokeWidth={strokeWidth}
            fill="none"
          />
          <Circle
            cx={size / 2}
            cy={size / 2}
            r={r}
            stroke={`url(#${id})`}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            fill="none"
            strokeDasharray={`${c} ${c}`}
            strokeDashoffset={c * (1 - shown / 100)}
          />
        </Svg>
      </View>
      <View style={[StyleSheet.absoluteFill, styles.center]}>
        {children ?? (
          <>
            <Text style={[styles.value, { color: colors.foreground, fontSize: size * 0.22 }]}>
              {Math.round(shown)}
              <Text style={{ fontSize: size * 0.12, color: colors.mutedForeground }}>%</Text>
            </Text>
            {label && (
              <Text style={[styles.label, { color: colors.mutedForeground }]}>{label}</Text>
            )}
          </>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  center: { alignItems: "center", justifyContent: "center" },
  value: { fontWeight: "700", letterSpacing: -1, fontVariant: ["tabular-nums"] },
