/** Animated: use the native driver everywhere except react-native-web. */
export const nativeDriver = Platform.OS !== "web";

/** Cross-platform elevation. Level 0–4. */
export function shadow(level: 0 | 1 | 2 | 3 | 4, scheme: ColorScheme = "light"): ViewStyle {
  if (level === 0) return {};
  const dark = scheme === "dark";
  const y = [0, 1, 4, 10, 18][level];
  const blur = [0, 3, 12, 28, 44][level];
  const alpha = (dark ? [0, 0.4, 0.5, 0.55, 0.6] : [0, 0.06, 0.08, 0.12, 0.16])[level];
  if (Platform.OS === "web") {
    return { boxShadow: `0px ${y}px ${blur}px rgba(0,0,0,${alpha})` } as ViewStyle;
  }
  return {
    shadowColor: "#000",
    shadowOffset: { width: 0, height: y },
    shadowOpacity: alpha,
    shadowRadius: blur / 2,
    elevation: level * 3,
  };
}

/** Hex color to rgba(). */
export function alpha(hex: string, a: number) {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.replace(/./g, (c) => c + c) : h, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

type ThemeValue = {
  scheme: ColorScheme;
  colors: ThemeColors;
  radius: typeof radius;
  space: typeof space;
  fontSize: typeof fontSize;
  fontWeight: typeof fontWeight;
  shadow: (level: 0 | 1 | 2 | 3 | 4) => ViewStyle;
};

const ThemeContext = React.createContext<{
  scheme?: ColorScheme;
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
} | null>(null);

export function ThemeProvider({
  scheme,
  colors,
  children,
}: {
  /** Force a scheme. Defaults to the device setting. */
  scheme?: ColorScheme;
  /** Override tokens per scheme, e.g. `{ light: { brand: "#7c3aed" } }`. */
  colors?: Partial<Record<ColorScheme, Partial<ThemeColors>>>;
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => ({ scheme, colors }), [scheme, colors]);
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useTheme(): ThemeValue {
  const ctx = React.useContext(ThemeContext);
  const system = useColorScheme();
  const scheme: ColorScheme = ctx?.scheme ?? (system === "dark" ? "dark" : "light");
  return React.useMemo(
    () => ({
      scheme,
      colors: { ...palette[scheme], ...(ctx?.colors?.[scheme] ?? {}) },
      radius,
      space,
      fontSize,
      fontWeight,
      shadow: (level: 0 | 1 | 2 | 3 | 4) => shadow(level, scheme),
    }),
    [scheme, ctx?.colors],
  );
}

import * as React from "react";
import {
  Animated,
  Pressable,
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { Icon, type IconName } from "@/components/native/icon";
import { nativeDriver, useTheme } from "@/components/native/theme";

export type ToggleProps = {
  icon: IconName;
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  /** Color when on. Defaults to red for hearts, the foreground otherwise. */
  activeColor?: string;
  /** Fill the icon while on (hearts, stars, bookmarks). */
  fillWhenActive?: boolean;
  /** Text next to the icon, e.g. a like count. */
  label?: string;
  /** Draw a bordered button around the icon. */
  bordered?: boolean;
  size?: number;
  accessibilityLabel: string;
  style?: StyleProp<ViewStyle>;
};

export function Toggle({
  icon,
  pressed,
  defaultPressed = false,
  onPressedChange,
  activeColor,
  fillWhenActive = true,
  label,
  bordered,
  size = 22,
  accessibilityLabel,
  style,
}: ToggleProps) {
  const { colors } = useTheme();
  const [inner, setInner] = React.useState(defaultPressed);
  const on = pressed ?? inner;
  const scale = React.useRef(new Animated.Value(1)).current;
  const burst = React.useRef(new Animated.Value(0)).current;
  const tint =
    activeColor ?? (icon === "heart" ? "#ef4444" : icon === "star" ? "#f5a524" : colors.foreground);

  const toggle = () => {
    const next = !on;
    if (pressed === undefined) setInner(next);
    onPressedChange?.(next);
    scale.setValue(next ? 0.6 : 0.9);
    Animated.spring(scale, {
      toValue: 1,
      useNativeDriver: nativeDriver,
      speed: 14,
      bounciness: 18,
    }).start();
    if (next) {
      burst.setValue(0);
      Animated.timing(burst, { toValue: 1, duration: 450, useNativeDriver: nativeDriver }).start();
    }
  };

  return (
    <Pressable
      accessibilityRole="switch"
      accessibilityState={{ checked: on }}
      accessibilityLabel={accessibilityLabel}
      onPress={toggle}
      hitSlop={6}
      style={[
        styles.root,
        bordered && [
          styles.bordered,
          { borderColor: on ? tint : colors.border, backgroundColor: colors.card },
        ],
        style,
      ]}
    >
      <View>
        {/* Ring burst on activation */}
        <Animated.View
          style={[
            StyleSheet.absoluteFill,
            styles.burst,
            {
              borderColor: tint,
              opacity: burst.interpolate({ inputRange: [0, 0.2, 1], outputRange: [0, 0.6, 0] }),
              transform: [
                { scale: burst.interpolate({ inputRange: [0, 1], outputRange: [0.4, 2] }) },
              ],
            },
          ]}
        />
        <Animated.View style={{ transform: [{ scale }] }}>
          <Icon
            name={icon}
            size={size}
            color={on ? tint : colors.mutedForeground}
            fill={on && fillWhenActive ? tint : "none"}
          />
        </Animated.View>
      </View>
      {label != null && (
        <Text style={[styles.label, { color: on ? tint : colors.mutedForeground }]}>{label}</Text>
      )}
    </Pressable>
  );
}

